        if ($steps > self::MAX_TURNS) {
            // Cat wins
            $this->memo[$key] = false;
            return false;
        }

        // 2) Cat occupies same position as mouse => Cat wins
        if ($mousePos === $catPos) {
            $this->memo[$key] = false;
            return false;
        }

        // 3) If cat reaches food first => Cat wins
        $foodPosInt = $this->posToInt($this->foodPos[0], $this->foodPos[1]);
        if ($catPos === $foodPosInt) {
            $this->memo[$key] = false;
            return false;
        }

