                        $this->memo[$key] = false;
                        return false;
                    }
                }
            }

            // Try staying in same position
            if (!$this->dfs($mousePos, $catPos, 0, $steps)) {
                $this->memo[$key] = false;
                return false;
            }

            // all cat moves checked, all allow mouse to win
            $this->memo[$key] = true;
            return true;
        }
    }

    private function isValid($r, $c) {
        return $r >= 0 && $r < $this->row && $c >= 0 && $c < $this->col;
    }

